/**
 * information-flow/load-monitor.ts — 角色负载追踪 (GAP-2: InformationFlow Phase 1)
 *
 * Tracks per-role load metrics: active tasks, token usage, queue depth.
 * In-memory for Phase 1; SQLite persistence to follow in Phase 2.
 */
import type { LoadSnapshot } from './types';
/** Get current load snapshot for a role */
export declare function getLoadSnapshot(roleId: string): LoadSnapshot;
/** Update a role's load metrics */
export declare function updateLoad(roleId: string, delta: {
    activeTasks?: number;
    tokensUsed?: number;
    queueDelta?: number;
}): LoadSnapshot;
/** Check if a role is overloaded (> 80% token budget used or queue > 5) */
export declare function isOverloaded(roleId: string): boolean;
/** Reset load data for a role */
export declare function resetLoad(roleId: string): void;
/** Reset all load data */
export declare function resetAllLoad(): void;
/** Get all role load snapshots */
export declare function getAllLoadSnapshots(): LoadSnapshot[];
